/// <summary>
///    The <c>UnitOfMeasureLookup</c> class provides the methods to perform lookup on the
///    <c>EcoResProduct</c> table, controls the <c>EcoResProductLookup</c> lookup form behavior, and
///    handles form events.
/// </summary>
internal class GUPEcoResCategoryHierarchyLookup
{
    private boolean returnRefRecID = false;

}

Method.Source:
final public boolean parmreturnRefRecID(boolean _returnRefRecID = returnRefRecID)
{
    returnRefRecID = _returnRefRecID;

    return returnRefRecID;
}

public EcoResCategoryHierarchy performLookup(FormStringControl _formStringControl)
{
    Args args = new Args();
    args.name(formStr(GUPEcoResCategoryHierarchyLookup));
    args.caller(this);

    args.parmObject(this);
    args.lookupField(fieldNum(EcoResCategoryHierarchy, RecId));
    args.lookupValue(_formStringControl.valueStr());

    FormRun formRun = classfactory.formRunClass(args);
    formRun.init();

    _formStringControl.performFormLookup(formRun);
    EcoResCategoryHierarchy ecoResCategoryHierarchy = formRun.selectRecordModeSelectedRecord() as EcoResCategoryHierarchy;

    return ecoResCategoryHierarchy;
}

public static GUPEcoResCategoryHierarchyLookup construct(boolean _returnRefRecID)
{
    return new GUPEcoResCategoryHierarchyLookup(_returnRefRecID);
}
